
import * as RAPIER from '@dimforge/rapier3d-compat';

// Avoid initializing WASM more than once.
let initializationPromise = null;

async function initializeRapier() {
  if (!initializationPromise) {
    initializationPromise = RAPIER.init({});
  }

  await initializationPromise;
}

// Create a physics world.
export async function createPhysicsWorld({
  gravity = { x: 0, y: -9.81, z: 0 },
  timestep = 1 / 60,
  maxSubSteps = 5,
} = {}) {
  await initializeRapier();

  const world = new RAPIER.World(gravity);

  world.timestep = timestep;

  // Collect collision events generated by Rapier.
  const eventQueue = new RAPIER.EventQueue(true);

  // Store events until the game reads them.
  const pendingCollisionEvents = [];

  // Fixed timestep accumulator.
  let accumulator = 0;

  function step(delta, afterStep = () => {}) {
    if (!Number.isFinite(delta) || delta <= 0) {
      return 0;
    }

    accumulator += Math.min(delta, 0.1);

    let subSteps = 0;

    while (accumulator >= timestep && subSteps < maxSubSteps) {
      // Step physics and collect collision events.
      world.step(eventQueue);
      afterStep(world, timestep);

      // Preserve events from this physics substep.
      eventQueue.drainCollisionEvents(
        (handle1, handle2, started) => {
          pendingCollisionEvents.push({
            collider1: handle1,
            collider2: handle2,
            started,
          });
        },
      );

      accumulator -= timestep;
      subSteps += 1;
    }

    if (subSteps >= maxSubSteps) {
      accumulator = Math.min(accumulator, timestep);
    }

    return subSteps;
  }

  // Retrieve collected collision events.
  function drainCollisionEvents() {
    return pendingCollisionEvents.splice(
      0,
      pendingCollisionEvents.length,
    );
  }

  // Release physics resources.
  function dispose() {
    eventQueue.free();
    world.free();

    accumulator = 0;
    pendingCollisionEvents.length = 0;
  }

  return {
    rapier: RAPIER,
    world,
    eventQueue,
    step,
    drainCollisionEvents,
    dispose,
    timestep,
  };
}
